import itertools
import pulp

def find_designs(n, k):
    edges = list(itertools.combinations(range(n), 2))
    triangles = list(itertools.combinations(range(n), 3))

    prob = pulp.LpProblem("Design", pulp.LpMinimize)
    x = pulp.LpVariable.dicts("x", triangles, 0, 1, pulp.LpBinary)

    for edge in edges:
        prob += pulp.lpSum([x[t] for t in triangles if set(edge).issubset(set(t))]) == k

    if prob.solve() == pulp.LpStatusOptimal:
        T = [t for t in triangles if pulp.value(x[t]) == 1]
        return T
    return None

def check_coloring(T, n):
    for coloring in itertools.product('RB', repeat=n):
        mono_count = 0
        for t in T:
            if coloring[t[0]] == coloring[t[1]] == coloring[t[2]]:
                mono_count += 1
        if mono_count <= 1:
            return True, coloring, mono_count
    return False, None, None

